package main

import (
	"context"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"
	pb "github.com/your-username/test-app/gen/go/test_app/v1"
	"github.com/your-username/test-app/internal/config"
	"github.com/your-username/test-app/internal/db"
	"github.com/your-username/test-app/internal/grpcserver"
	"github.com/your-username/test-app/internal/tracing"
	"go.opentelemetry.io/contrib/instrumentation/google.golang.org/grpc/otelgrpc"
	"google.golang.org/grpc"
	"google.golang.org/grpc/health"
	healthpb "google.golang.org/grpc/health/grpc_health_v1"
	"google.golang.org/grpc/reflection"
)

func main() {
	log := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	slog.SetDefault(log)

	cfg, err := config.Load()
	if err != nil {
		log.Error("config", "err", err)
		os.Exit(1)
	}

	// closers run in reverse on shutdown (tracing flush, APM stop).
	var closers []func(context.Context) error
	if shutdown, err := tracing.Init(context.Background(), cfg.AppName); err != nil {
		log.Warn("tracing disabled", "err", err)
	} else {
		closers = append(closers, shutdown)
	}
	gormDB, err := db.OpenGorm(cfg.DatabaseURL)
	if err != nil {
		log.Error("database", "err", err)
		os.Exit(1)
	}
	if sqlDB, err := gormDB.DB(); err == nil {
		closers = append(closers, func(context.Context) error { return sqlDB.Close() })
	}

	lis, err := net.Listen("tcp", ":"+cfg.Port)
	if err != nil {
		log.Error("listen", "err", err)
		os.Exit(1)
	}

	grpcSrv := grpc.NewServer(
		grpc.StatsHandler(otelgrpc.NewServerHandler()), // one span per RPC
		grpc.ChainUnaryInterceptor(
			grpcserver.Metrics(),
			grpcserver.RateLimit(),
			grpcserver.Audit(log),
			grpcserver.Auth(),
		),
		grpc.ChainStreamInterceptor(
			grpcserver.MetricsStream(),
			grpcserver.RateLimitStream(),
			grpcserver.AuditStream(log),
		),
	)

	pb.RegisterUserServiceServer(grpcSrv, grpcserver.NewUserService(gormDB))
	pb.RegisterPostServiceServer(grpcSrv, grpcserver.NewPostService(gormDB))

	// Standard gRPC health service — probes use grpc-health-probe or
	// the grpc.health.v1.Health endpoint.
	healthSrv := health.NewServer()
	healthpb.RegisterHealthServer(grpcSrv, healthSrv)
	healthSrv.SetServingStatus("", healthpb.HealthCheckResponse_SERVING)

	// Server reflection makes tools like grpcurl / bloomrpc work without a proto file.
	reflection.Register(grpcSrv)

	// Prometheus scrapes this plain-HTTP listener; the gRPC port only speaks HTTP/2.
	metricsAddr := ":" + os.Getenv("METRICS_PORT")
	if metricsAddr == ":" {
		metricsAddr = ":9464"
	}
	metricsSrv := &http.Server{Addr: metricsAddr, Handler: promhttp.Handler(), ReadHeaderTimeout: 10 * time.Second}
	go func() {
		if err := metricsSrv.ListenAndServe(); !errors.Is(err, http.ErrServerClosed) {
			log.Error("metrics", "err", err)
		}
	}()

	go func() {
		log.Info("gRPC server listening", "addr", lis.Addr().String())
		if err := grpcSrv.Serve(lis); err != nil {
			log.Error("serve", "err", err)
			os.Exit(1)
		}
	}()

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer stop()
	<-ctx.Done()

	log.Info("shutdown requested; draining connections")
	healthSrv.SetServingStatus("", healthpb.HealthCheckResponse_NOT_SERVING)
	grpcSrv.GracefulStop()

	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = metricsSrv.Shutdown(shutdown)
	for i := len(closers) - 1; i >= 0; i-- {
		if err := closers[i](shutdown); err != nil {
			log.Warn("shutdown", "err", err)
		}
	}
}

