package db

import (
	"errors"
	"fmt"
	"strings"

	"github.com/golang-migrate/migrate/v4"
	_ "github.com/golang-migrate/migrate/v4/database/pgx/v5"
	"github.com/golang-migrate/migrate/v4/source/iofs"

	"github.com/your-username/test-app/migrations"
)

// NewMigrate opens golang-migrate on the embedded migrations/*.sql.
func NewMigrate(databaseURL string) (*migrate.Migrate, error) {
	dbURL, err := migrateURL(databaseURL)
	if err != nil {
		return nil, fmt.Errorf("DATABASE_URL: %w", err)
	}
	src, err := iofs.New(migrations.FS, ".")
	if err != nil {
		return nil, err
	}
	return migrate.NewWithSourceInstance("iofs", src, dbURL)
}

// Migrate applies pending migrations; the api runs it before serving. Safe with
// many replicas: golang-migrate holds a database lock while migrating (advisory
// lock on Postgres, GET_LOCK on MySQL), so one replica applies the migrations
// and the others find nothing to do.
func Migrate(databaseURL string) error {
	m, err := NewMigrate(databaseURL)
	if err != nil {
		return err
	}
	defer m.Close()
	if err := m.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
		return fmt.Errorf("migrate up: %w", err)
	}
	return nil
}

// migrateURL swaps the scheme for pgx5:// so golang-migrate connects with pgx,
// like the app does (lib/pq's sslmode=require default rejects a local Postgres).
func migrateURL(raw string) (string, error) {
	if _, rest, ok := strings.Cut(raw, "://"); ok {
		return "pgx5://" + rest, nil
	}
	return raw, nil
}

internal/db/sql.go:
package db

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
)

// Open connects to the database and retries transient errors with exponential
// backoff (up to ~30s total). Kubernetes pods frequently come up before their
// database StatefulSet / managed instance accepts connections — without retry
// the API pod restarts and delays rollout.
//
// Pool sizing (25 open / 10 idle / 30m lifetime) is a sane default for a
// single-instance API. Tune it to your database's connection limit.
func Open(dsn string) (*sql.DB, error) {
	// db: postgres
	conn, err := sql.Open("pgx", dsn)
	if err != nil {
		return nil, fmt.Errorf("sql.Open: %w", err)
	}
	conn.SetMaxOpenConns(25)
	conn.SetMaxIdleConns(10)
	conn.SetConnMaxLifetime(30 * time.Minute)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	var lastErr error
	backoff := 200 * time.Millisecond
	for attempt := 1; attempt <= 6; attempt++ {
		if err := conn.PingContext(ctx); err == nil {
			return conn, nil
		} else {
			lastErr = err
			if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
				break
			}
			log.Printf("db: ping failed (attempt %d/6): %v — retrying in %s", attempt, err, backoff)
			select {
			case <-ctx.Done():
				return nil, fmt.Errorf("db: context cancelled while retrying: %w", ctx.Err())
			case <-time.After(backoff):
			}
			backoff *= 2
			if backoff > 5*time.Second {
				backoff = 5 * time.Second
			}
		}
	}
	return nil, fmt.Errorf("db: could not connect after retries: %w", lastErr)
}

