package grpcserver

import (
	"context"
	"log/slog"
	"net"
	"net/http"
	"slices"
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promauto"
	"github.com/your-username/test-app/internal/auth"
	"golang.org/x/time/rate"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/peer"
	"google.golang.org/grpc/status"
)

// peerIP is the client address without the port.
func peerIP(ctx context.Context) string {
	p, ok := peer.FromContext(ctx)
	if !ok {
		return "unknown"
	}
	host, _, err := net.SplitHostPort(p.Addr.String())
	if err != nil {
		return p.Addr.String()
	}
	return host
}

// ponytail: per-instance, in-memory token bucket keyed by client IP. With N
// replicas a client effectively gets N x the budget and state resets on
// restart — move the buckets to Redis (e.g. github.com/go-redis/redis_rate)
// when you need one global limit.
const (
	rateLimitRPS   = 10 // sustained requests per second per client IP
	rateLimitBurst = 20 // short bursts allowed above the sustained rate
	// ponytail: the table is dropped wholesale when full; an LRU would keep hot clients.
	maxTrackedIPs = 100_000
)

type ipLimiter struct {
	mu      sync.Mutex
	clients map[string]*rate.Limiter
}

func newIPLimiter() *ipLimiter { return &ipLimiter{clients: map[string]*rate.Limiter{}} }

func (l *ipLimiter) allow(ip string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	lim, ok := l.clients[ip]
	if !ok {
		if len(l.clients) >= maxTrackedIPs {
			clear(l.clients)
		}
		lim = rate.NewLimiter(rateLimitRPS, rateLimitBurst)
		l.clients[ip] = lim
	}
	return lim.Allow()
}

// limiter is shared so unary calls and stream opens draw from one bucket per IP.
var limiter = newIPLimiter()

// RateLimit rejects RPCs with ResourceExhausted once a client IP exceeds its bucket.
func RateLimit() grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req any, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (any, error) {
		if !limiter.allow(peerIP(ctx)) {
			return nil, status.Error(codes.ResourceExhausted, "rate_limited")
		}
		return handler(ctx, req)
	}
}

// RateLimitStream is RateLimit for streaming RPCs.
// ponytail: charges one token per stream open, not per message; wrap
// grpc.ServerStream.RecvMsg if long-lived streams need per-message limits.
func RateLimitStream() grpc.StreamServerInterceptor {
	return func(srv any, ss grpc.ServerStream, _ *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
		if !limiter.allow(peerIP(ss.Context())) {
			return status.Error(codes.ResourceExhausted, "rate_limited")
		}
		return handler(srv, ss)
	}
}

