// protectedRPCs are the entity RPCs whose REST routes require auth.
var protectedRPCs = []string{
	"/test_app.v1.UserService/ListUser",
	"/test_app.v1.UserService/GetUser",
	"/test_app.v1.UserService/CreateUser",
	"/test_app.v1.UserService/DeleteUser",
}

// Auth requires a valid bearer token in the "authorization" metadata for
// protectedRPCs, checked by the same verifier (internal/auth) as the REST
// middleware. Innermost in the chain, like the REST route-level guard.
func Auth() grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req any, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (any, error) {
		if !slices.Contains(protectedRPCs, info.FullMethod) {
			return handler(ctx, req)
		}
		md, _ := metadata.FromIncomingContext(ctx)
		h := http.Header{}
		for _, v := range md.Get("authorization") {
			h.Add("Authorization", v)
		}
		raw, err := auth.ExtractBearer(h)
		if err != nil {
			return nil, status.Error(codes.Unauthenticated, "missing_or_malformed_token")
		}
		v, err := auth.Default()
		if err != nil {
			return nil, status.Error(codes.Internal, "auth_unconfigured")
		}
		claims, err := v.Verify(ctx, raw)
		if err != nil {
			return nil, status.Error(codes.Unauthenticated, "invalid_token")
		}
		return handler(auth.NewContext(ctx, claims), req)
	}
}

