package grpcserver

import (
	"errors"
	"log/slog"
	"strings"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"google.golang.org/protobuf/types/known/timestamppb"
	"gorm.io/gorm"
)

// pageOf applies the List defaults: page 1, 20 items, at most 100 per page.
func pageOf(page, size uint32) (uint32, uint32) {
	if page == 0 {
		page = 1
	}
	if size == 0 {
		size = 20
	}
	return page, min(size, 100)
}

// asTime converts an optional Timestamp; unset maps to the zero time.
func asTime(ts *timestamppb.Timestamp) time.Time {
	if ts == nil {
		return time.Time{}
	}
	return ts.AsTime()
}

// dbError maps a data-layer error to a gRPC status. Unexpected errors are
// logged and answered with Internal so driver details don't reach clients.
func dbError(err error) error {
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return status.Error(codes.NotFound, "not found")
	}
	// ponytail: matches the driver's wording (Postgres "duplicate key", MySQL
	// "Duplicate entry", SQLite "UNIQUE constraint failed"). Set
	// gorm.Config{TranslateError: true} to rely on gorm.ErrDuplicatedKey alone.
	msg := strings.ToLower(err.Error())
	if errors.Is(err, gorm.ErrDuplicatedKey) || strings.Contains(msg, "duplicate") || strings.Contains(msg, "unique constraint") {
		return status.Error(codes.AlreadyExists, "already exists")
	}
	slog.Error("database", "err", err)
	return status.Error(codes.Internal, "internal error")
}

